Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
f2fs: fix node_cnt race between extent node destroy and
 writeback

f2fs_destroy_extent_node() does not set FI_NO_EXTENT before clearing
extent nodes. When called from f2fs_drop_inode() with I_SYNC set,
concurrent kworker writeback can insert new extent nodes into the same
extent tree, racing with the destroy and triggering f2fs_bug_on() in
__destroy_extent_node(). The scenario is as follows:

drop inode                            writeback
 - iput
  - f2fs_drop_inode  // I_SYNC set
   - f2fs_destroy_extent_node
    - __destroy_extent_node
     - while (node_cnt) {
        write_lock(&et->lock)
        __free_extent_tree
        write_unlock(&et->lock)
                                       - __writeback_single_inode
                                        - f2fs_outplace_write_data
                                         - f2fs_update_read_extent_cache
                                          - __update_extent_tree_range
                                           // FI_NO_EXTENT not set,
                                           // insert new extent node
       } // node_cnt == 0, exit while
     - f2fs_bug_on(node_cnt)  // node_cnt > 0

Additionally, __update_extent_tree_range() only checks FI_NO_EXTENT for
EX_READ type, leaving EX_BLOCK_AGE updates completely unprotected.

This patch set FI_NO_EXTENT under et->lock in __destroy_extent_node(),
consistent with other callers (__update_extent_tree_range and
__drop_extent_tree) and check FI_NO_EXTENT for both EX_READ and
EX_BLOCK_AGE tree.

Fixes: 3fc5d5a182f6 ("f2fs: fix to shrink read extent node in batches")
Cc: stable@vger.kernel.org
Signed-off-by: Yongpeng Yang <yangyongpeng@xiaomi.com>
Reviewed-by: Chao Yu <chao@kernel.org>
Signed-off-by: Jaegeuk Kim <jaegeuk@kernel.org>

Here is the root cause:
The `__destroy_extent_node()` function clears extent nodes without setting the `FI_NO_EXTENT` flag under the extent tree lock, allowing concurrent writeback to insert new extent nodes into the same tree via `__update_extent_tree_range()`. Additionally, the `FI_NO_EXTENT` check in `__update_extent_tree_range()` and `__may_extent_tree()` only applied to `EX_READ` type, leaving `EX_BLOCK_AGE` updates unprotected. This race leads to a mismatched `node_cnt` triggering a `f2fs_bug_on()`.

Here is the patch:

 static bool __may_extent_tree(struct inode *inode, enum extent_type type)
 {
 	if (IS_DEVICE_ALIASING(inode) && type == EX_READ)
 		return true;

 	/*
 	 * for recovered files during mount do not create extents
 	 * if shrinker is not registered.
 	 */
 	if (list_empty(&F2FS_I_SB(inode)->s_list))
 		return false;

 	if (!__init_may_extent_tree(inode, type))
 		return false;

+	if (is_inode_flag_set(inode, FI_NO_EXTENT))
+		return false;
+
 	if (type == EX_READ) {
-		if (is_inode_flag_set(inode, FI_NO_EXTENT))
-			return false;
 		if (is_inode_flag_set(inode, FI_COMPRESSED_FILE) &&
 				 !f2fs_sb_has_readonly(F2FS_I_SB(inode)))
 			return false;
 	} else if (type == EX_BLOCK_AGE) {
 		if (is_inode_flag_set(inode, FI_COMPRESSED_FILE))
 			return false;
 		if (file_is_cold(inode))
 			return false;
 	}
 	return true;
 }


 static unsigned int __destroy_extent_node(struct inode *inode,
 					enum extent_type type)
 {
 	struct f2fs_sb_info *sbi = F2FS_I_SB(inode);
 	struct extent_tree *et = F2FS_I(inode)->extent_tree[type];
 	unsigned int nr_shrink = type == EX_READ ?
 				READ_EXTENT_CACHE_SHRINK_NUMBER :
 				AGE_EXTENT_CACHE_SHRINK_NUMBER;
 	unsigned int node_cnt = 0;

 	if (!et || !atomic_read(&et->node_cnt))
 		return 0;

 	while (atomic_read(&et->node_cnt)) {
 		write_lock(&et->lock);
+		if (!is_inode_flag_set(inode, FI_NO_EXTENT))
+			set_inode_flag(inode, FI_NO_EXTENT);
 		node_cnt += __free_extent_tree(sbi, et, nr_shrink);
 		write_unlock(&et->lock);
 	}

 	f2fs_bug_on(sbi, atomic_read(&et->node_cnt));

 	return node_cnt;
 }

 static void __update_extent_tree_range(struct inode *inode,
 			struct extent_info *tei, enum extent_type type)
 {
 	struct f2fs_sb_info *sbi = F2FS_I_SB(inode);
 	struct extent_tree *et = F2FS_I(inode)->extent_tree[type];
 	struct extent_node *en = NULL, *en1 = NULL;
 	struct extent_node *prev_en = NULL, *next_en = NULL;
 	struct extent_info ei, dei, prev;
 	struct rb_node **insert_p = NULL, *insert_parent = NULL;
 	unsigned int fofs = tei->fofs, len = tei->len;
 	unsigned int end = fofs + len;
 	bool updated = false;
 	bool leftmost = false;

 	if (!et)
 		return;

 	if (unlikely(len == 0)) {
 		f2fs_err_ratelimited(sbi, "%s: extent len is zero, type: %d, "
 			"extent [%u, %u, %u], age [%llu, %llu]",
 			__func__, type, tei->fofs, tei->blk, tei->len,
 			tei->age, tei->last_blocks);
 		f2fs_bug_on(sbi, 1);
 		return;
 	}

 	if (type == EX_READ)
 		trace_f2fs_update_read_extent_tree_range(inode, fofs, len,
 						tei->blk, 0);
 	else if (type == EX_BLOCK_AGE)
 		trace_f2fs_update_age_extent_tree_range(inode, fofs, len,
 						tei->age, tei->last_blocks);

 	write_lock(&et->lock);

-	if (type == EX_READ) {
-		if (is_inode_flag_set(inode, FI_NO_EXTENT)) {
-			write_unlock(&et->lock);
-			return;
-		}
+	if (is_inode_flag_set(inode, FI_NO_EXTENT)) {
+		write_unlock(&et->lock);
+		return;
+	}

+	if (type == EX_READ) {
 		prev = et->largest;
 		dei.len = 0;

 		/*
 		 * drop largest extent before lookup, in case it's already
 		 * been shrunk from extent tree
 		 */
 		__drop_largest_extent(et, fofs, len);
 	}

 	/* 1. lookup first extent node in range [fofs, fofs + len - 1] */
 	en = __lookup_extent_node_ret(&et->root,
 					et->cached_en, fofs,
 					&prev_en, &next_en,
 					&insert_p, &insert_parent,
 					&leftmost);
 	if (!en)
 		en = next_en;

 	/* 2. invalidate all extent nodes in range [fofs, fofs + len - 1] */
 	while (en && en->ei.fofs < end) {
 		unsigned int org_end;
 		int parts = 0;	/* # of parts current extent split into */

 		next_en = en1 = NULL;

 		dei = en->ei;
 		org_end = dei.fofs + dei.len;
 		f2fs_bug_on(sbi, fofs >= org_end);

 		if (fofs > dei.fofs && (type != EX_READ ||
 				fofs - dei.fofs >= F2FS_MIN_EXTENT_LEN)) {
 			en->ei.len = fofs - en->ei.fofs;
 			prev_en = en;
 			parts = 1;
 		}

 		if (end < org_end && (type != EX_READ ||
 			(org_end - end >= F2FS_MIN_EXTENT_LEN &&
 			atomic_read(&et->node_cnt) <
 					sbi->max_read_extent_count))) {
 			if (parts) {
 				__set_extent_info(&ei,
 					end, org_end - end,
 					end - dei.fofs + dei.blk, false,
 					dei.age, dei.last_blocks,
 					type);
 				en1 = __insert_extent_tree(sbi, et, &ei,
 							NULL, NULL, true);
 				next_en = en1;
 			} else {
 				__set_extent_info(&en->ei,
 					end, en->ei.len - (end - dei.fofs),
 					en->ei.blk + (end - dei.fofs), true,
 					dei.age, dei.last_blocks,
 					type);
 				next_en = en;
 			}
 			parts++;
 		}

 		if (!next_en) {
 			struct rb_node *node = rb_next(&en->rb_node);

 			next_en = rb_entry_safe(node, struct extent_node,
 						rb_node);
 		}

 		if (parts)
 			__try_update_largest_extent(et, en);
 		else
 			__release_extent_node(sbi, et, en);

 		/*
 		 * if original extent is split into zero or two parts, extent
 		 * tree has been altered by deletion or insertion, therefore
 		 * invalidate pointers regard to tree.
 		 */
 		if (parts != 1) {
 			insert_p = NULL;
 			insert_parent = NULL;
 		}
 		en = next_en;
 	}

 	if (type == EX_BLOCK_AGE)
 		goto update_age_extent_cache;

 	/* 3. update extent in read extent cache */
 	BUG_ON(type != EX_READ);

 	if (tei->blk) {
 		__set_extent_info(&ei, fofs, len, tei->blk, false,
 				  0, 0, EX_READ);
 		if (!__try_merge_extent_node(sbi, et, &ei, prev_en, next_en))
 			__insert_extent_tree(sbi, et, &ei,
 					insert_p, insert_parent, leftmost);

 		/* give up extent_cache, if split and small updates happen */
 		if (dei.len >= 1 &&
 				prev.len < F2FS_MIN_EXTENT_LEN &&
 				et->largest.len < F2FS_MIN_EXTENT_LEN) {
 			et->largest.len = 0;
 			et->largest_updated = true;
 			set_inode_flag(inode, FI_NO_EXTENT);
 		}
 	}

 	if (et->largest_updated) {
 		et->largest_updated = false;
 		updated = true;
 	}
 	goto out_read_extent_cache;
 update_age_extent_cache:
 	if (tei->last_blocks == F2FS_EXTENT_AGE_INVALID)
 		goto out_read_extent_cache;

 	__set_extent_info(&ei, fofs, len, 0, false,
 			tei->age, tei->last_blocks, EX_BLOCK_AGE);
 	if (!__try_merge_extent_node(sbi, et, &ei, prev_en, next_en))
 		__insert_extent_tree(sbi, et, &ei,
 					insert_p, insert_parent, leftmost);
 out_read_extent_cache:
 	write_unlock(&et->lock);

 	if (is_inode_flag_set(inode, FI_NO_EXTENT))
 		__destroy_extent_node(inode, EX_READ);

 	if (updated)
 		f2fs_mark_inode_dirty_sync(inode, true);
 }



